function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function batteryStatus(){const show=(level,charging)=>{const el=$('#batteryLevel');if(!el)return;el.style.width=Math.max(8,Math.round(level*100))+'%';el.parentElement.classList.toggle('low',level<=.2&&!charging);el.parentElement.classList.toggle('charging',!!charging);el.parentElement.dataset.level=Math.round(level*100)};show(1,false);navigator.getBattery?.().then(b=>{const u=()=>show(b.level,b.charging);u();b.addEventListener('levelchange',u);b.addEventListener('chargingchange',u)}).catch(()=>{})}batteryStatus();
