function editRole(id=null){editing=id;const r=roles.find(x=>x.id===id),f=$('#roleForm');f.reset();f.elements.namedItem('name').value=r?.name||'';f.emoji.value=r?.emoji||'🌷';f.prompt.value=r?.prompt||'';$('#editor h2').textContent=r?'编辑角色':'创建你的角色';roleAvatarDraft=mediaCache.get('role:'+id)||null;$('#roleAvatarPreview').innerHTML=roleAvatarDraft?`<span class="avatar"><img src="${roleAvatarDraft}" alt="角色头像预览"></span>`:avatarHTML('role:'+id,r?.emoji||'🌷');$('#roleAvatarFile').value='';$('#chooseRoleAvatar').onclick=()=>$('#roleAvatarFile').click();$('#roleAvatarFile').onchange=async e=>{const b=$('#chooseRoleAvatar'),save=$('#roleForm button[type="submit"]');b.disabled=true;save.disabled=true;try{roleAvatarDraft=await prepareImage(e.target.files[0]);$('#roleAvatarPreview').innerHTML=`<span class="avatar"><img src="${roleAvatarDraft}" alt="角色头像预览"></span>`}catch(err){toast(err.message)}finally{b.disabled=false;save.disabled=false;e.target.value=''}};$('#clearRoleAvatar').onclick=()=>{roleAvatarDraft=null;$('#roleAvatarPreview').innerHTML='<span class="avatar">'+escapeHtml(f.emoji.value||'🌷')+'</span>'};$('#editor').showModal()}
$('#cancelRole').onclick=()=>$('#editor').close();$('#roleForm').onsubmit=async e=>{e.preventDefault();const f=e.target;const name=f.elements.namedItem('name').value.trim(),prompt=f.prompt.value.trim();if(!name||!prompt)return;const r={id:editing||crypto.randomUUID(),name,emoji:f.emoji.value.trim()||'🌷',prompt};const oldRoles=roles;const save=f.querySelector('button[type="submit"]');save.disabled=true;try{await mediaWrite('role:'+r.id,roleAvatarDraft);roles=editing?roles.map(x=>x.id===editing?r:x):[...roles,r];persist();$('#editor').close();toast('角色已保存');go('chat')}catch(err){roles=oldRoles;toast(err.message||'保存失败，请重试')}finally{save.disabled=false}};
function renderApi(){screen.innerHTML=`<section class="view">${title('API 设置','CHAT & VOICE CONNECTION')}<div class="notice">支持 OpenAI 兼容接口。每位使用者填写自己的地址、密钥和模型。</div><div class="api-section-title"><span>01</span><h3>聊天 API</h3><p>文字聊天、角色动态与记忆整理</p></div><form id="apiForm"><label>接口地址 · Base URL<input name="base" type="url" placeholder="https://你的接口域名/v1" required value="${escapeHtml(config.base)}"></label><label>API Key<input name="key" type="password" autocomplete="off" placeholder="填写你的 API 密钥" required value="${escapeHtml(key)}"></label><div class="model-setting"><div class="model-label">聊天模型<button class="text-button" type="button" id="loadModels">↻ 获取模型</button></div><input name="model" type="hidden" value="${escapeHtml(config.model)}"><select id="modelSelect" aria-label="选择聊天模型"><option value="${escapeHtml(config.model)}">${escapeHtml(config.model||'先点击「获取模型」')}</option></select><label id="modelManual" hidden>手动输入模型名称<input id="manualModelInput" placeholder="填写服务商提供的模型名称" value="${escapeHtml(config.model)}"></label><button class="text-button" type="button" id="manualModel">接口不支持列表？手动输入</button></div><label class="check"><input type="checkbox" name="remember" ${config.remember?'checked':''}>在此浏览器记住密钥（仅在自己的设备上开启）</label><div class="actions"><button class="secondary" type="button" id="testApi">测试连接</button><button class="primary">保存配置</button></div></form><div class="connection" id="connection" role="status"></div><p class="api-note">地址可填 /v1 或完整 /chat/completions 地址。请求从你的浏览器直接发送至所填接口，服务商需允许跨域访问（CORS）。密钥默认只留在当前页面内存中。</p>${visionPanelHTML()}<div id="voiceAPISection"></div></section>`;renderVoiceSettings(true);$('#checkVision').onclick=checkVision;const apiForm=$('#apiForm');$('#loadModels').onclick=()=>loadModels(apiForm);$('#modelSelect').onchange=e=>{apiForm.model.value=e.target.value};$('#manualModelInput').oninput=e=>{apiForm.model.value=e.target.value.trim()};$('#manualModel').onclick=()=>{$('#modelSelect').hidden=true;$('#modelManual').hidden=false;$('#manualModelInput').value=apiForm.model.value;$('#manualModelInput').focus();$('#manualModel').hidden=true};const resetModels=()=>{$('#modelSelect').replaceChildren(new Option('接口已更改，请重新获取模型',''));apiForm.model.value='';$('#manualModelInput').value='';$('#modelSelect').hidden=false;$('#modelManual').hidden=true;$('#manualModel').hidden=false};apiForm.base.oninput=resetModels;apiForm.key.oninput=resetModels;$('#apiForm').onsubmit=e=>{e.preventDefault();if(!apiForm.model.value.trim()){toast('请先获取并选择模型，或手动输入');return}saveConfig(e.target);toast('API 配置已保存');$('#visionStatus').textContent=visionStatus();memoryTick()};$('#testApi').onclick=async()=>{const f=$('#apiForm');if(!f.reportValidity())return;if(!f.model.value.trim()){toast('请先选择模型');return}const c=formConfig(f);const btn=$('#testApi'),status=$('#connection');btn.disabled=true;status.textContent='正在测试连接…';try{const result=await request(c,[{role:'user',content:'请只回复：连接成功'}],64);status.textContent='✓ 连接成功 · '+result.slice(0,80)}catch(err){status.textContent='连接失败：'+friendly(err)}finally{btn.disabled=false}}}
function formConfig(f){return {base:f.base.value.trim().replace(/\/+$/,''),key:f.key.value.trim(),model:f.model.value.trim(),remember:f.remember.checked}}
function saveConfig(f){const c=formConfig(f);key=c.key;config=c;localStorage.setItem('palais.config',JSON.stringify({...c,key:c.remember?key:''}))}
function endpoint(base){return PalaisCore.apiURL(base,'chat/completions')}
async function request(c,messages,max_tokens=1024,signal){const res=await fetch(endpoint(c.base),{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+c.key},body:JSON.stringify({model:c.model,messages,stream:false,max_tokens}),signal:signal||AbortSignal.timeout(45000)});let data;try{data=await res.json()}catch{throw Error('接口没有返回有效的 JSON（HTTP '+res.status+'）')}if(!res.ok)throw Error('HTTP '+res.status+' · '+(data.error?.message||'请求失败'));const content=data.choices?.[0]?.message?.content;if(typeof content!=='string'||!content.trim())throw Error('接口没有返回可用的回复，请检查模型与兼容格式');return content}
function friendly(err){if(err.name==='AbortError')return '已停止生成';if(err.name==='TimeoutError')return '连接超时，请稍后重试';if(err instanceof TypeError)return '无法访问接口，请检查地址、网络及服务商的 CORS 设置';return err.message}
function renderConversation(){
  const r=findConversation(current);if(!r){current=null;render();return}markChatSeen(r.id);
  screen.innerHTML=`<section class="chatview"><header class="chat-head"><button id="back" aria-label="返回聊天列表">‹</button>${avatarHTML('role:'+r.id,r.emoji)}<div class="identity">${escapeHtml(r.name)}<small>${busy?'正在回复…':r.members?r.members.length+' 位角色 · 群聊':'记忆在这里，故事继续'}</small></div><button id="editCurrent" aria-label="聊天功能与设置">⋯</button></header><div class="messages" id="messages" aria-live="polite"></div><div id="chatError" role="status"></div><div class="chat-actions"><button id="recordMessage" aria-label="录音转文字">♫</button><button id="giftMessage">＋ 心意卡片</button><button id="chatStickers">☺ 表情包</button><button id="chatMemory">♧ 记忆</button>${r.members?'<button id="groupIntro">自我介绍</button>':''}</div><form class="composer" id="composer"><textarea rows="1" placeholder="写下想说的话…" aria-label="聊天消息" ${busy?'disabled':''}></textarea><button class="primary" aria-label="${busy?'停止生成':'发送消息'}" type="${busy?'button':'submit'}" id="send">${busy?'■':'↑'}</button></form></section>`;
  $('#back').onclick=()=>{current=null;render()};$('#editCurrent').onclick=()=>openChatTools(r);$('#recordMessage').onclick=()=>startRecording(r);$('#giftMessage').onclick=()=>sendGift(r);$('#chatStickers').onclick=()=>openStickerPicker(r);$('#chatMemory').onclick=()=>go('memory');if($('#groupIntro'))$('#groupIntro').onclick=()=>introduceGroup(r);
  const history=histories[r.id]||[],messages=$('#messages'),background=mediaCache.get('background:'+r.id)||mediaCache.get('background:default');if(background){messages.classList.add('custom-background');messages.style.backgroundImage=`linear-gradient(#fffaf530,#fffaf530),url("${background}")`}
  messages.innerHTML=history.length?'<div class="conversation-date">你们的私语时光</div>':`<div class="empty-chat"><span>${escapeHtml(r.emoji)}</span>从一句「你好」开始吧。<br><small>聊天与记忆仅保存在当前浏览器。</small></div>`;
  history.forEach((m,index)=>{const el=document.createElement('div'),speaker=roles.find(x=>x.id===m.sender)||r;if(m.kind==='pat'){el.className='pat-event';el.textContent=m.content;messages.append(el);return}el.className='msg '+m.role;el.innerHTML='<div class="message-meta">'+(m.role==='assistant'?avatarHTML('role:'+speaker.id,speaker.emoji):avatarHTML('profile','🎀'))+chatStampHTML(m)+'</div>'+`<div class="message-body">${r.members&&m.role==='assistant'?`<small class="sender-name">${escapeHtml(speaker.name)}</small>`:''}<div class="bubble">${escapeHtml(m.sticker&&/^\[表情包[：:]/.test(m.content)?'':m.content)}${stickerHTML(m)}${cardHTML(m)}</div>${m.role==='assistant'?`<button class="text-button speak-message" data-speak="${index}" aria-label="朗读这条回复">♫ 朗读</button>`:''}</div>`;el.querySelector('.avatar').ondblclick=()=>patAvatar(r,m);messages.append(el)});
  if(busy){const el=document.createElement('div');el.className='msg';el.innerHTML='<div class="bubble">正在酝酿一句温柔…</div>';messages.append(el)}messages.scrollTop=messages.scrollHeight;
  document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await playSpeech(history[Number(b.dataset.speak)].content)}catch(err){toast(friendly(err))}finally{b.disabled=false}});
  document.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>{const m=history.find(m=>m.id===b.dataset.receive);receiveGift(r,m)});
  $('#composer').onsubmit=e=>{e.preventDefault();sendMessage(r,$('#composer textarea').value.trim())};$('#composer textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#composer').requestSubmit()}};if(busy)$('#send').onclick=()=>controller?.abort();
}
function openChatTools(r){const d=panel(`<h2>聊天小工具</h2><button class="menu-button" id="toolsAppearance">聊天背景与头像 <span>›</span></button>${r.members?'<button class="menu-button" id="toolsGroup">群聊成员与氛围 <span>›</span></button>':''}<button class="menu-button" id="toolsVoice">语音聊天 <span>♫</span></button><button class="menu-button" id="toolsMemory">查看长期记忆 <span>♧</span></button><button class="menu-button" id="toolsWorld">世界书 <span>›</span></button><button class="secondary full" id="closeTools">关闭</button>`);$('#closeTools').onclick=()=>d.close();$('#toolsAppearance').onclick=()=>{d.close();openAppearance(r)};if($('#toolsGroup'))$('#toolsGroup').onclick=()=>{d.close();editGroup(r.id)};$('#toolsVoice').onclick=()=>{d.close();openVoiceChat(r)};$('#toolsMemory').onclick=()=>{d.close();go('memory')};$('#toolsWorld').onclick=()=>{d.close();go('book')}}
async function sendMessage(r,value,card=null,options={}){
  if(!value||busy||phoneLocked)return false;if(!requireAPI())return false;
  const id=r.id,audience=r.members?.slice(),hist=histories[id]||(histories[id]=[]),user={id:crypto.randomUUID(),role:'user',content:value,createdAt:Date.now(),...(audience?{audience}:{}),...(card?{card}: {}),...(options.sticker?{sticker:options.sticker}:{})};const previousWallet=wallet;try{if(card)wallet=PalaisWallet.apply(wallet,{messageId:user.id,conversationId:id,amount:card.amount,direction:'out',type:card.type,note:card.note,peer:r.name});hist.push(user);persist()}catch(err){if(hist.at(-1)===user)hist.pop();wallet=previousWallet;toast(err.message||'浏览器存储空间不足，请导出备份');return false}
  busy=true;controller=new AbortController();const signal=controller.signal,timer=setTimeout(()=>controller?.abort(),180000);render();let lastReply='',ok=true;
  try{
    await consolidate(id);if(!r.members)await consolidate('shared:'+id);if(signal.aborted||phoneLocked)throw new DOMException('Stopped','AbortError');
    const speakers=audience?audience.map(id=>roles.find(x=>x.id===id)).filter(x=>x&&(!options.intro||!(r.introduced||[]).includes(x.id))):[r];
    for(const speaker of speakers){if(signal.aborted||phoneLocked)throw new DOMException('Stopped','AbortError');
      const system=PalaisCore.systemPrompt(speaker,worldbook,r.members?groupSeen(r,speaker.id):hist,r.id)+'\n\n'+(r.members?groupMemory(r,speaker.id):memoryPrompt(id)+'\n'+sharedContext(speaker.id))+'\n'+relationshipPrompt(speaker.id)+homeRelationshipPrompt(speaker.id)+'\n\n当前用户称呼：'+profile.name+(r.members?'\n你正在群聊「'+r.name+'」中，其他成员是'+speakers.map(x=>x.name).join('、')+'。群聊氛围：'+r.prompt+'。你们因同群而认识，但没有公开说过的身份与关系细节不能假装知道。只扮演你自己，不代替其他成员说话。'+(options.intro?'这一轮请用2–4句话介绍自己的身份和与用户的关系，仅使用你自己的人设，不透露私聊记录，不猜测其他成员身份。':'自然回应最近的对话。'):'')+'\n需要表达心意时，可以使用虚拟卡片格式 [[红包|金额|祝福]] 或 [[转账|金额|留言]]，金额必须大于0且不超过100000，仅用于角色扮演，不涉及真实资金。不要每次都送卡片。';
      const text=await request({...config,key},await buildChatMessages(system,(r.members?groupSeen(r,speaker.id):hist).slice(-40)),1200,signal);if(phoneLocked||signal.aborted)throw new DOMException('Stopped','AbortError');const parsed=parseChatReply(text);const reply={id:crypto.randomUUID(),role:'assistant',sender:speaker.id,createdAt:Date.now(),...(audience?{audience}:{}),...parsed};hist.push(reply);try{persist()}catch(err){hist.pop();throw err}if(options.intro){r.introduced=[...new Set([...(r.introduced||[]),speaker.id])];saveSocial()}incomingMessage(r,speaker,reply);lastReply=parsed.content;if(isChatView()&&current===id)renderConversation();
    }
  }catch(err){ok=false;reportVisionFailure(err);toast(friendly(err));if(isChatView()&&current===id){busy=false;renderConversation();$('#chatError').className='error';$('#chatError').textContent=friendly(err)+'。已收到的回复和你的消息会保留。'}}
  finally{clearTimeout(timer);busy=false;controller=null;render()}
  if(ok&&lastReply&&(voiceMode||voiceSettings.autoPlay))try{await playSpeech(lastReply)}catch(err){toast(friendly(err))}
  memoryTick();return ok;
}
