function renderMe(){const count=Object.values(histories).reduce((n,a)=>n+a.length,0);screen.innerHTML=`<section class="view">${title('我的小宫殿','A WORLD OF YOUR OWN')}<div class="profile-card">${avatarHTML('profile','🎀')}<h3>${escapeHtml(profile.name)}</h3><button class="text-button" id="editProfile">编辑人物与头像 ↗</button><p>今天，也要把温柔留一点给自己。</p></div><div class="stats"><div><strong>${roles.length}</strong>位角色</div><div><strong>${count}</strong>条私语</div></div><div class="notice">进入密码暂时关闭，网站继续仅你可访问。</div><button class="menu-button" id="openTheme">主题配色 <span>${escapeHtml(themeName())} ›</span></button><button class="menu-button" data-go="memory">长期记忆与整理规则 <span>›</span></button><button class="menu-button" data-go="wechat">打开微信 <span>›</span></button><button class="menu-button" id="exportData">导出小宫殿备份 <span>↗</span></button><button class="menu-button" data-go="book">世界书 <span>›</span></button><button class="menu-button" data-go="api">管理 API 配置 <span>›</span></button><button class="menu-button" id="clearKey">清除保存的 API 密钥 <span>×</span></button><p class="section-note">记录仅保存在当前浏览器，暂不跨设备同步。<br>备份包含日程与经期记录，不包含 API 密钥和解锁密码。<br>ROSE PALAIS · 私人小宫殿</p></section>`;$('#exportData').onclick=()=>download('玫瑰小宫殿-聊天备份.json',{roles,histories,worldbook,profile,groups,moments,events,periods,periodCycle,memories,memorySettings,voiceSettings,wallet,relations,feedEvents,socialSettings,notices,customStickers,proactive,homeland,desktopTodos,desktopWeather,images:Object.fromEntries(mediaCache),exportedAt:new Date().toISOString()});$('#editProfile').onclick=renderProfile;$('#openTheme').onclick=()=>openThemePicker(renderMe);$('#clearKey').onclick=()=>{key='';voiceKey='';voiceConfig.key='';voiceConfig.remember=false;localSave('voiceConfig',voiceConfig);localSave('voiceConnection',{config:voiceConfig,settings:voiceSettings});config.key='';config.remember=false;localStorage.setItem('palais.config',JSON.stringify(config));toast('API 密钥已清除')}}
